// MANDATORY Postgres-before-binary-consumer pattern: the Postgres node above
// replaced the item and dropped item.binary. Re-establish it ONCE, by node
// reference from the trigger, directly before the consumer.
return [{ json: $json, binary: $('When Called by WF-001').first().binary }];

// SW-029 — compute the storage key and validate the bytes before any upload.
//
// Content type and extension come from MAGIC BYTES, never from the Drive
// mimeType (finding: probe E). The date partition comes from
// documents.uploaded_at, never from wall-clock (finding H2). The bytes are
// verified against documents.sha256 before anything is stored (M2b).

const trig = $('When Called by WF-001').first().json;
const row  = $json || {};

if (!row.document_id) {
  throw new Error('SW-029: no repository.documents row for documentId=' +
    (trig.documentId || '(missing)') + '. Register the document before persisting its original.');
}

const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
if (!buf || buf.length === 0) {
  throw new Error('SW-029: binary property "data" is empty or absent — the original file did not cross the workflow boundary.');
}
const byteSize = buf.length;

// --- M2b: the bytes MUST be the bytes this document claims to be -------------
// The object is NAMED for documents.sha256, so storing a buffer that hashes to
// anything else would file the wrong content under that fingerprint and make
// every later integrity check compare an object against a hash it never had.
// Verify-on-write checks size (M2); this checks identity. The Code node has no crypto
// API, so this is a pure-JS SHA-256 -- but a STREAMING one: it compresses 64-byte
// blocks straight out of the source buffer and allocates only a fixed 64/128-byte
// tail. The variant in WF-001's Init builds the padded message as one new array the
// size of the whole file, which for a 12.7 MB document is a 12.1 MiB allocation whose
// only purpose is to append nine bytes of padding. Digests are bit-identical; asserted
// against Node's crypto across 260 cases including every block-boundary edge case.
function sha256Hex(bytes) {
  const b = (bytes instanceof Uint8Array) ? bytes : new Uint8Array(bytes);
  const K = new Uint32Array([
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2]);
  let h0=0x6a09e667,h1=0xbb67ae85,h2=0x3c6ef372,h3=0xa54ff53a,h4=0x510e527f,h5=0x9b05688c,h6=0x1f83d9ab,h7=0x5be0cd19;
  const w = new Uint32Array(64);
  const rotr = (x,n) => (x>>>n)|(x<<(32-n));

  // compress one 64-byte block read at `off` from Uint8Array `src`
  function block(src, off) {
    for (let i=0;i<16;i++) {
      const j = off + i*4;
      w[i] = ((src[j]<<24)|(src[j+1]<<16)|(src[j+2]<<8)|src[j+3])>>>0;
    }
    for (let i=16;i<64;i++){
      const s0=rotr(w[i-15],7)^rotr(w[i-15],18)^(w[i-15]>>>3);
      const s1=rotr(w[i-2],17)^rotr(w[i-2],19)^(w[i-2]>>>10);
      w[i]=(w[i-16]+s0+w[i-7]+s1)|0;
    }
    let a=h0,b1=h1,c=h2,d=h3,e=h4,f=h5,g=h6,h=h7;
    for (let i=0;i<64;i++){
      const S1=rotr(e,6)^rotr(e,11)^rotr(e,25);
      const ch=(e&f)^(~e&g);
      const t1=(h+S1+ch+K[i]+w[i])|0;
      const S0=rotr(a,2)^rotr(a,13)^rotr(a,22);
      const maj=(a&b1)^(a&c)^(b1&c);
      const t2=(S0+maj)|0;
      h=g;g=f;f=e;e=(d+t1)|0;d=c;c=b1;b1=a;a=(t1+t2)|0;
    }
    h0=(h0+a)|0;h1=(h1+b1)|0;h2=(h2+c)|0;h3=(h3+d)|0;
    h4=(h4+e)|0;h5=(h5+f)|0;h6=(h6+g)|0;h7=(h7+h)|0;
  }

  const l = b.length;
  const full = l - (l % 64);
  for (let off = 0; off < full; off += 64) block(b, off);      // no copy: read in place

  // tail: remaining bytes + 0x80 + zero pad + 64-bit big-endian bit length.
  // 128 bytes covers both the one-block and two-block padding cases.
  const rem = l - full;
  const tail = new Uint8Array(rem + 9 <= 64 ? 64 : 128);
  for (let i = 0; i < rem; i++) tail[i] = b[full + i];
  tail[rem] = 0x80;
  const bitLen = l * 8;
  const dv = new DataView(tail.buffer);
  dv.setUint32(tail.length - 4, bitLen >>> 0, false);
  dv.setUint32(tail.length - 8, Math.floor(bitLen / 0x100000000), false);
  for (let off = 0; off < tail.length; off += 64) block(tail, off);

  const hex = x => ('00000000'+(x>>>0).toString(16)).slice(-8);
  return [h0,h1,h2,h3,h4,h5,h6,h7].map(hex).join('');
}

const actualSha = sha256Hex(buf);
if (String(row.sha256).toLowerCase() !== actualSha) {
  throw new Error('SW-029: content fingerprint mismatch for documentId=' + row.document_id +
    '. repository.documents.sha256=' + row.sha256 + ' but the bytes on the wire hash to ' +
    actualSha + '. Refusing to store: the object key is derived from that hash, so storing ' +
    'these bytes would file the wrong content under it.');
}

// --- format: derived from CONTENT, never from the Drive mimeType -------------
// Google-native documents arrive as PDF (googleFileConversion) while Drive still
// reports application/vnd.google-apps.* — trusting that value keys the object
// with the wrong extension and makes SW-005's detectFormat() misclassify it.
const hex = (n) => buf.slice(0, n).toString('hex').toUpperCase();
let contentType = null, ext = null;

if (buf.slice(0, 4).toString('latin1') === '%PDF')            { contentType = 'application/pdf';  ext = 'pdf'; }
else if (hex(8) === '89504E470D0A1A0A')                        { contentType = 'image/png';        ext = 'png'; }
else if (hex(3) === 'FFD8FF')                                  { contentType = 'image/jpeg';       ext = 'jpg'; }
else if (hex(4) === '49492A00' || hex(4) === '4D4D002A')        { contentType = 'image/tiff';       ext = 'tiff'; }
else if (hex(4) === '504B0304' || hex(4) === '504B0506' || hex(4) === '504B0708') {
  // OOXML is a ZIP. The subtype is still decided from the BYTES, not from metadata:
  // the part names are stored as plain text in the zip directory, so the presence of
  // word/ vs xl/ vs ppt/ identifies the format. WF-001 ingests .docx today, so a
  // narrower allowlist here would regress documents the repository already holds.
  // A ZIP names its parts twice: in the local file headers at the START and again in
  // the central directory at the END. Two bounded windows therefore identify the
  // subtype without materialising the whole file as a string -- buf.toString() on a
  // 12.7 MB document allocates a multi-megabyte string purely to look for a fixed
  // marker. If the windows miss (unusually many parts, or a very large central
  // directory) fall back to the full scan BEFORE throwing, so the bounded path is a
  // performance shortcut and never a correctness change.
  const WINDOW = 262144;
  let probe;
  if (buf.length <= WINDOW * 2) {
    probe = buf.toString('latin1');
  } else {
    probe = buf.slice(0, WINDOW).toString('latin1') +
            buf.slice(buf.length - WINDOW).toString('latin1');
    if (!/word\/document\.xml|xl\/workbook\.xml|ppt\/presentation\.xml/.test(probe)) {
      probe = buf.toString('latin1');
    }
  }
  if (probe.includes('word/document.xml')) {
    contentType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'; ext = 'docx';
  } else if (probe.includes('xl/workbook.xml')) {
    contentType = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'; ext = 'xlsx';
  } else if (probe.includes('ppt/presentation.xml')) {
    contentType = 'application/vnd.openxmlformats-officedocument.presentationml.presentation'; ext = 'pptx';
  } else {
    throw new Error('SW-029: file is a ZIP container but not a recognised OOXML document ' +
      '(no word/, xl/ or ppt/ part). Refusing to store an object whose extension cannot be ' +
      'derived from its content.');
  }
}

if (!contentType) {
  throw new Error('SW-029: unsupported or unrecognised file type (first bytes ' + hex(8) +
    '). Refusing to store an object whose extension cannot be derived from its content.');
}

// --- size gate (H6): fail here, not after the expensive OCR step ---
const maxBytes = Number($env.CRIE_STORAGE_MAX_BYTES) || 0;
if (maxBytes > 0 && byteSize > maxBytes) {
  throw new Error('SW-029: file is ' + byteSize + ' bytes, above CRIE_STORAGE_MAX_BYTES=' + maxBytes + '.');
}

const endpoint = ($env.CRIE_STORAGE_ENDPOINT || '').replace(/\/+$/, '');
const bucket   = $env.CRIE_STORAGE_BUCKET || '';
if (!endpoint || !bucket) {
  throw new Error('SW-029: CRIE_STORAGE_ENDPOINT and CRIE_STORAGE_BUCKET must be set on the n8n instance (resolved from configuration/storage.yaml).');
}

// --- key: originals/{yyyy}/{mm}/{dd}/{documentId}/{sha256}.{ext} ---
const storageKey = 'originals/' + row.uploaded_partition + '/' + row.document_id + '/' + row.sha256 + '.' + ext;

return [{
  json: {
    correlationId: trig.correlationId || null,
    documentId: row.document_id,
    sha256: row.sha256,
    storageKey,
    storageBucket: bucket,
    storageEndpoint: endpoint,
    contentType,
    byteSize,
    hasExistingKey: !!row.storage_key,
    existingStorageKey: row.storage_key || null
  },
  binary: $input.first().binary
}];

// M2 verify-on-write: the object we just stored must report the size we sent.
const prep = $('Prepare Object').item.json;
const info = $json || {};
const reported = Number(info.size ?? (info.metadata && info.metadata.size));

if (!Number.isFinite(reported)) {
  throw new Error('SW-029: could not read a size back for ' + prep.storageKey + ' — refusing to record an unverified storage_key.');
}
if (reported !== prep.byteSize) {
  throw new Error('SW-029: stored size ' + reported + ' != uploaded size ' + prep.byteSize +
    ' for ' + prep.storageKey + ' — refusing to record a storage_key for a corrupt object.');
}

return [{ json: { ...prep, verifiedBytes: reported } }];

// Terminal node. Reached by two MUTUALLY EXCLUSIVE paths (uploaded / skipped),
// so it reads only $json — the current branch's item — and never reaches across
// branches. See docs/IMPLEMENTATION_NOTES.md 'Execution semantics'.
const prep = $('Prepare Object').item.json;
const j = $json || {};
const skipped = !j.stored_at;

return [{ json: {
  workflow_id: 'SW-029',
  correlationId: prep.correlationId,
  documentId: prep.documentId,
  sha256: prep.sha256,
  storageKey: skipped ? prep.existingStorageKey : j.storage_key,
  storageBucket: skipped ? prep.storageBucket : j.storage_bucket,
  contentType: skipped ? prep.contentType : j.content_type,
  byteSize: skipped ? prep.byteSize : Number(j.byte_size),
  storedAt: skipped ? null : j.stored_at,
  skippedUpload: skipped
} }];
